rules.implementation:
dir_col = next((c for c in value.columns if c not in ("DiffusionBValue", "Count")), None)
if dir_col is None:
    raise ValidationWarning("Cannot count directions (no gradient orientation field available).")
rows = value
b0_thr = params.get("b0_threshold")
if "DiffusionBValue" in value.columns and b0_thr is not None:
    b = value["DiffusionBValue"].fillna(0).astype(float)
    rows = value[b > b0_thr]
dirs = set()
for o in rows[dir_col]:
    if o is None or o != o:
        continue
    try:
        dirs.add(tuple(round(float(x), 3) for x in as_list(o)))
    except (TypeError, ValueError):
        dirs.add(str(o))
n = len(dirs)
exact = params.get("exact_directions")
if exact is not None:
    if n != exact:
        raise ValidationError(f"Expected exactly {exact} unique diffusion directions, found {n}.")
else:
    min_n = params.get("min_directions")
    if min_n is not None and n < min_n:
        raise ValidationError(f"Only {n} unique diffusion directions; at least {min_n} required.")
    rec = params.get("recommended_directions")
    if rec is not None and n < rec:
        raise ValidationWarning(f"{n} unique diffusion directions; {rec}+ recommended.")

spec = params.get("shell_spec") or ""
tol = params.get("shell_tolerance") if params.get("shell_tolerance") is not None else 100
b = value["DiffusionBValue"].fillna(0).astype(float)
counts = value["Count"]
problems = []
for part in [p.strip() for p in spec.split(",") if p.strip()]:
    center_str, _, rng = part.partition(":")
    center = float(center_str)
    n = int(counts[(b - center).abs() <= tol].sum())
    if "-" in rng:
        lo_str, hi_str = rng.split("-", 1)
        lo, hi = float(lo_str), float(hi_str)
    else:
        lo, hi = float(rng), None
    if n < lo:
        problems.append(f"b~{center:g}: found {n} images, expected >= {lo:g}")
    elif hi is not None and n > hi:
        problems.append(f"b~{center:g}: found {n} images, expected <= {hi:g}")
if problems:
    raise ValidationError("; ".join(problems))

n = value["EchoTime"].dropna().nunique()
exact = params.get("exact_echoes")
if exact is not None:
    if n != exact:
        raise ValidationError(f"Expected exactly {exact} echoes, found {n}.")
else:
    min_n = params.get("min_echoes")
    if min_n is not None and n < min_n:
        raise ValidationError(f"Only {n} echoes; at least {min_n} required.")
    rec = params.get("recommended_echoes")
    if rec is not None and n < rec:
        raise ValidationWarning(f"Found {n} echoes; {rec}+ recommended.")

# Validate magnitude/phase pairs per echo
for echo_time, group in value.groupby("EchoTime"):
    image_types = group["ImageType"]

    # ImageType is list-valued; check components, not the string repr
    has_magnitude = any("M" in as_list(it) for it in image_types)
    has_phase = any("P" in as_list(it) for it in image_types)

    if not has_magnitude:
        raise ValidationError(f"Echo time {echo_time} ms is missing magnitude image.")

    if not has_phase:
        raise ValidationError(f"Echo time {echo_time} ms is missing phase image.")
